INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
  (29548, 0, 0, 0, 0, 0, 0, 0, 0, 'That''s a whole Horde base down there!$BWhere was our intel!$B$BWell $c, it''s time to see what this upgraded gunship is capable of.', 0),
  (29576, 0, 0, 0, 0, 0, 0, 0, 0, 'if you''ve come to speak with my fists, take your place in line. Otherwise, I could use your help.', 0),
  (29578, 0, 0, 0, 0, 0, 0, 0, 0, 'Nice work, but there''s more to be done if we are to save this village.', 0),
  (29580, 0, 0, 0, 0, 0, 0, 0, 0, 'There are no hunters among us, but we''ll fight to protect our loved ones.', 0),
  (29581, 0, 0, 0, 0, 0, 0, 0, 0, 'Ah... dreamleaf! So you want to see the Golden Dream, do you?$B$BCome to think of it, I haven''t seen the Dream in years - not since I was a cub spending long hours playing in the pools. Long before I took up the culinary arts.$B$BLooks like you brought enough dreamleaf for two cups of tea... so why not?$B$BHere''s to better days!', 0),
  (29585, 0, 0, 0, 0, 0, 0, 0, 0, 'A survivor came in moments ago and said the flames are beginning to die down.$B$BWe owe our very way of life to you, stranger. I cannot possibly reward you adequately, but please take this.', 0),
  (29600, 0, 0, 0, 0, 0, 0, 0, 0, 'You have my gratitude, $n.\r\n\r\nPlease take this as a token of my appreciation.', 0),
  (29670, 0, 0, 0, 0, 0, 0, 0, 0, 'This is extremely unsettling. If mogu are banding together like this all over the continent, it could become a major threat to Pandaria.', 0),
  (29873, 0, 0, 0, 0, 0, 0, 0, 0, 'This place... it... it so SAD!\r\n\r\nKen-Ken never seen a place so sad.', 0),
  (29881, 0, 0, 0, 0, 0, 0, 0, 0, 'Ah! You have a wonderful eye for color my friend. These will make a superb pigment.', 0),
  (29882, 0, 0, 0, 0, 0, 0, 0, 0, 'My thanks traveler. These will make a fine set of quills. Here is something for your trouble.', 0),
  (29909, 0, 0, 0, 0, 0, 0, 0, 0, 'Wha-? Who the...? My father sent you?\r\n\r\nPshh... he can be so nosy sometimes. I have everything under control here.', 0),
  (29911, 0, 0, 0, 0, 0, 0, 0, 0, 'Ho ho! Now that''s what I like to see!', 0),
  (29916, 0, 0, 0, 0, 0, 0, 0, 0, 'They... they''re not stopping, but at least we fought back. Right?', 0),
  (29917, 0, 0, 0, 0, 0, 0, 0, 0, 'I know I should be the one fighting them off. Maybe I''m not cut out for shepherding after all.', 0),
  (29981, 0, 0, 0, 0, 0, 0, 0, 0, 'Lin asked you to help us out? Rather presumptive of her.\r\n\r\nStill, we are short-manned. We won''t turn down your help... or the girl''s. You have our thanks, $c.', 0),
  (29983, 0, 0, 0, 0, 0, 0, 0, 0, 'You seek training?\r\n\r\n<The pandaren studies your physique for several seconds. without speaking.>\r\n\r\nAlright.', 0),
  (29990, 0, 0, 0, 0, 0, 0, 0, 0, 'I''m glad to hear that Lin is well.\r\n\r\nOur defenses are holding, for now. The mantid continue to send their scouts over the wall, but they haven''t gotten much farther than that.', 0),
  (29993, 0, 0, 0, 0, 0, 0, 0, 0, 'You seek two lovers blind to the ambitions of their family names. They were here, seeking a way to hold to their path.\r\n\r\nSadly they did not find their answers among the trees of art.', 0),
  (30028, 0, 0, 0, 0, 0, 0, 0, 0, 'Why thank you very much stranger. This has not been a good day, but you certainly have helped us make it better.\r\n\r\nPlease, take this, you''ve earned it.', 0),
  (30029, 0, 0, 0, 0, 0, 0, 0, 0, 'Thank you for your help stranger!\r\nHopefully we can deal with the rest on our own from here.', 0),
  (30030, 0, 0, 0, 0, 0, 0, 0, 0, 'Now that that''s over I have some ideas on how to make a new concoction. We''ll see.\r\n\r\nThank you for your help. Here is your reward.', 0),
  (30059, 0, 0, 0, 0, 0, 0, 0, 0, 'It seems like there''s not QUITE as many corrupted moths out there. At the very least, you''ve bought me some more time before I get in big, big trouble.', 0),
  (30064, 0, 0, 0, 0, 0, 0, 0, 0, 'Thank you! What a relief it is to see these texts are safe.', 0),
  (30069, 0, 0, 0, 0, 0, 0, 0, 0, 'Great work! If you ever decide to give up your life of adventure, the SI:7 could use more talent like you...', 0),
  (30072, 0, 0, 0, 0, 0, 0, 0, 0, 'Superb specimens. I will see to it they find their way to the right place. Please enjoy this free sample.', 0),
  (30081, 0, 0, 0, 0, 0, 0, 0, 0, 'Pandaren got a case of the spooky-dooks!\r\n\r\nDooks get scared sometimes, don''t wanna come out. Poor, fluffy mopey-dopes must be ready to explode by now!\r\n\r\nThis just the thing to bring ''em out. That make pandaren happy for sure!\r\n\r\nJust like ol'' gramma used to say: can''t THROW if can''t GO!', 0),
  (30134, 0, 0, 0, 0, 0, 0, 0, 0, 'Thank goodness, they finally sent someone!\r\n\r\nThings have gotten out of control!', 0),
  (30135, 0, 0, 0, 0, 0, 0, 0, 0, 'Thank you, $c.\r\n\r\nI tried to stop the Slitherscale where I could, but I was no match for their numbers.\r\n\r\nYour work today will help preserve an entire generation of cloud serpents.', 0),
  (30137, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh, wonderful!\r\n\r\nThese eggs look...well...they look a little on the small side. Are you sure you couldn''t find any better ones?\r\n\r\nOh well, I suppose with the current situation, we can''t be so picky.', 0),
  (30159, 0, 0, 0, 0, 0, 0, 0, 0, 'Will those nasty Slitherscale saurok never give up?', 0),
  (30160, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh, is this for me? I-I don''t know what to say.$B$BIt''s very pretty, thank you!', 0),
  (30181, 0, 0, 0, 0, 0, 0, 0, 0, 'Well done $n.\r\n\r\nMy father travels across the sea to a new continent and all he can seem ta'' want to hunt is old borin'' wolves.\r\n\r\nMe, I like to hunt stuff with meat on its bones.', 0),
  (30184, 0, 0, 0, 0, 0, 0, 0, 0, 'Now that''s a proper trophy right there.', 0),
  (30189, 0, 0, 0, 0, 0, 0, 0, 0, 'Really? For me?$B$BSuch a lovely apple shouldn''t be eaten alone.$B$BHere, please have half.', 0),
  (30267, 0, 0, 0, 0, 0, 0, 0, 0, 'Finally, someone who understands me.\r\nFishing is what it''s all about, right?\r\n\r\nMaybe I should leave New Cifera... just pack up my things and join the Anglers, down in the south. Of course, I couldn''t leave my family behind...\r\n\r\nBut still... a pandaren can dream, right?', 0),
  (30351, 0, 0, 0, 0, 0, 0, 0, 0, 'That''s it! You pick, I punch!', 0),
  (30379, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh my, this is a flawless jewel!$B$BIf you keep giving me gifts like these, I may have to retire early!', 0),
  (30380, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh, what a lovely apple! These sweet fruits are quite the treat around here.', 0),
  (30381, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh, a jade cat!$B$BMy father and I used to hunt for these in the fields. He always said they were lucky.', 0),
  (30382, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh, thank you. This beautiful feather is just lovely.', 0),
  (30383, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh my, these are quite rare. Thank you for giving it to me.', 0),
  (30387, 0, 0, 0, 0, 0, 0, 0, 0, 'What an interesting little figurine. It''s quite lovely. Thank you, dear.', 0),
  (30388, 0, 0, 0, 0, 0, 0, 0, 0, 'Such a pretty feather would fetch a nice price at market, but I''m not selling this one. Thank you for the gift.', 0),
  (30389, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh wonderful! You''ve brought me a Marsh Lily.$B$BHow did you know that these are my favorite?', 0),
  (30391, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh, for me? Well, I guess that''s mighty nice of you.', 0),
  (30392, 0, 0, 0, 0, 0, 0, 0, 0, 'Well ain''t that sweet of ya. Hmph.', 0),
  (30393, 0, 0, 0, 0, 0, 0, 0, 0, 'Hmph, well that is mighty fine of you to think of me like that.$B$BThank ye.', 0),
  (30394, 0, 0, 0, 0, 0, 0, 0, 0, '...$B$BMy son, Tai...he used to collect these as a little boy.$B$BWhen his mother died, I told him they were messages from her, fallen from the heavens.$B$B<Old Hillpaw falls into a quiet silence.>', 0),
  (30395, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh, these flowers are quite rare.$B$BYou know that these are considered lucky? Maybe my harvest will go well after all. Thank you.', 0),
  (30397, 0, 0, 0, 0, 0, 0, 0, 0, 'Pretty stone! You silly for giving away. Oh well, mine now!$B$BThanks, $r!', 0),
  (30398, 0, 0, 0, 0, 0, 0, 0, 0, 'For me? Red apple? So shiny! So juicy! Thanks, boss!', 0),
  (30399, 0, 0, 0, 0, 0, 0, 0, 0, 'Ooh, very old, very valuable. Me like kitties. Got one from girl Ella.', 0),
  (30400, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh my. You know what this is? A frikfrak! Frikfrak for chief only!$B$BWhich mean...you must think me is chief? We boss buddy now, $n.', 0),
  (30401, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh! Pretty flower! No takebacks boss, okay? Thank you, bye!', 0),
  (30403, 0, 0, 0, 0, 0, 0, 0, 0, 'For me? Why thank you.', 0),
  (30404, 0, 0, 0, 0, 0, 0, 0, 0, 'Thank you.', 0),
  (30405, 0, 0, 0, 0, 0, 0, 0, 0, 'I appreciate the sentiment, $r.', 0),
  (30406, 0, 0, 0, 0, 0, 0, 0, 0, 'I appreciate your gesture, $r. Thank you for thinking of me.', 0),
  (30407, 0, 0, 0, 0, 0, 0, 0, 0, 'I have never been one to dwell on pretty, useless things, but I know you give me this gift out of friendship. For that, I thank you. Whenever I look at this flower, I will think of you.', 0),
  (30422, 0, 0, 0, 0, 0, 0, 0, 0, 'Ooh, now I never seen such a purty red stone. Thank ya, $n!', 0),
  (30423, 0, 0, 0, 0, 0, 0, 0, 0, 'My stomach''s been rumbling all mornin''! This is a perfect gift.', 0),
  (30424, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh, a pretty jade cat! This makes me real happy, $n!', 0),
  (30425, 0, 0, 0, 0, 0, 0, 0, 0, 'Whoa, I never seen such a purty color before. Thanks, $n!', 0),
  (30426, 0, 0, 0, 0, 0, 0, 0, 0, 'My pappy always said these flowers bring lotsa luck. Thanks, $n!', 0),
  (30459, 0, 0, 0, 0, 0, 0, 0, 0, 'Thank you, $n. You''ve saved our defensive line here.\r\n\r\nThis next attack wouldn''t have been possible without you.', 0),
  (30500, 0, 0, 0, 0, 0, 0, 0, 0, 'This is terrible...\r\n\r\nWe must find a way to undo what has been done here.', 0),
  (30626, 0, 0, 0, 0, 0, 0, 0, 0, 'I see.\r\n\r\nWell, we gave it out all. It''s time to evacuate, save lives, and reassess our strategy, before these mantid take over the entire valley.r the entire valley.', 0),
  (30628, 0, 0, 0, 0, 0, 0, 0, 0, 'Peering inside, you find...', 0),
  (30891, 0, 0, 0, 0, 0, 0, 0, 0, 'Marvelous. And in good condition too!\r\n\r\nThank you, kind $c.', 0),
  (30972, 0, 0, 0, 0, 0, 0, 0, 0, 'Taran Zhu told me what became of my camp. I would have stopped it if I could, but the attacks from the bridge have not let up.\r\n\r\nThank you for bringing these arrows - my archers will make good use of them.', 0),
  (31007, 0, 0, 0, 0, 0, 0, 0, 0, 'A few less traitors for us to feed to the kunchong when the dust settles.', 0),
  (31018, 0, 0, 0, 0, 0, 0, 0, 0, 'You have done your duty well, Wakener.', 0),
  (31071, 0, 0, 0, 0, 0, 0, 0, 0, 'You have brought me joy, traveler.', 0),
  (31107, 0, 0, 0, 0, 0, 0, 0, 0, 'They are large. They will hatch soon.\r\n\r\nGood. We may need them.', 0),
  (31133, 0, 0, 0, 0, 0, 0, 0, 0, 'You''ve got the makings of a fine brewgarden guard, $r. Let me know if you ever get tired of the whole "$c" thing.', 0),
  (31200, 0, 0, 0, 0, 0, 0, 0, 0, 'Nice, I can see the smoke from here. That should definitely cause some confusion!', 0),
  (31231, 0, 0, 0, 0, 0, 0, 0, 0, 'I never liked spiders. Filthy, mindless insects.', 0),
  (31267, 0, 0, 0, 0, 0, 0, 0, 0, 'Well done. With access to this amber, we shall be able to craft weapons to our cause.', 0),
  (31286, 0, 0, 0, 0, 0, 0, 0, 0, 'Ah, our merchandise. Madam Goya will be pleased. You have the gratitude of her ladyship.', 0),
  (31287, 0, 0, 0, 0, 0, 0, 0, 0, 'The deed is done and a debt must be paid. Here is your reward. You have our gratitude.', 0),
  (31288, 0, 0, 0, 0, 0, 0, 0, 0, 'Ah! Some fine pieces here. Very fine pieces indeed. My thanks, adventurer. ', 0),
  (31302, 0, 0, 0, 0, 0, 0, 0, 0, 'You are ready. You are now a zen master cook. ', 0),
  (31311, 0, 0, 0, 0, 0, 0, 0, 0, 'Good cuts. ', 0),
  (31387, 0, 0, 0, 0, 0, 0, 0, 0, 'Ah yes. $n. Your name has traveled to us from the east.$B$BWe have seen your efforts in the Vale of Eternal Blossoms. Already you have earned the esteem of the Golden Lotus.$B$BYes, we are interested to learn more about you.', 0),
  (31389, 0, 0, 0, 0, 0, 0, 0, 0, 'Ah yes. $n. Your name has traveled to us from the east.$B$BWe have seen your efforts in the Vale of Eternal Blossoms. Already you have earned the esteem of the Golden Lotus.$B$BYes, we are interested to learn more about you.', 0),
  (31467, 0, 0, 0, 0, 0, 0, 0, 0, 'Strength and good health! This is the Way of the Grill. ', 0),
  (31470, 0, 0, 0, 0, 0, 0, 0, 0, 'Well done. ', 0),
  (31471, 0, 0, 0, 0, 0, 0, 0, 0, 'Nice work. ', 0),
  (31472, 0, 0, 0, 0, 0, 0, 0, 0, 'Good stuff. Now, let''s get to your lesson. ', 0),
  (31474, 0, 0, 0, 0, 0, 0, 0, 0, 'Intellect is a gift you must hone with time. ', 0),
  (31475, 0, 0, 0, 0, 0, 0, 0, 0, 'Fine ingredients. ', 0),
  (31476, 0, 0, 0, 0, 0, 0, 0, 0, 'Spirits are lifted by good food. ', 0),
  (31477, 0, 0, 0, 0, 0, 0, 0, 0, 'Stamina and endurance are needed for mastering anything. To slave over a hot oven takes patience, but the results are very much worth the effort. ', 0),
  (31478, 0, 0, 0, 0, 0, 0, 0, 0, 'We can work with these. ', 0),
  (31479, 0, 0, 0, 0, 0, 0, 0, 0, 'This is a fine example of good ginseng. Would you like to learn how to make tea with it? ', 0),
  (31480, 0, 0, 0, 0, 0, 0, 0, 0, 'Well done. This is delicious. ', 0),
  (31486, 0, 0, 0, 0, 0, 0, 0, 0, 'My, that''s so thoughtful. I love hearing from my old students.', 0),
  (31535, 0, 0, 0, 0, 0, 0, 0, 0, 'Your help is very much appreciated. This will make a great difference for some of our students. ', 0),
  (31539, 0, 0, 0, 0, 0, 0, 0, 0, 'This... This is beyond my wildest expectations. This will be treasured and preserved for generations to come. ', 0),
  (31660, 0, 0, 0, 0, 0, 0, 0, 0, 'Their eggs should have basked in the warmth of the sun and the song of a million wings for ten more years.\r\n\r\nThe Empress will pay for her crimes.', 0),
  (31689, 0, 0, 0, 0, 0, 0, 0, 0, 'In disciplined hands, the spear is the perfect weapon. Only the weak would augment it with sorcery.\r\n\r\nAnd we have no need for the weak.', 0),
  (31706, 0, 0, 0, 0, 0, 0, 0, 0, 'Instructor Skythorn updated me on the situation at The Widow''s Wall. You have done well.', 0),
  (31727, 0, 0, 0, 0, 0, 0, 0, 0, 'So the bugs have taken an interest in us have they? Well if they want somethin'' from us they''ll have to come and earn it themselves!\r\n\r\nYou work for what you get here. That means you too!', 0),
  (31730, 0, 0, 0, 0, 0, 0, 0, 0, 'So they want us to leave do they? What a selfish request! We''re only taking amber from one tree.\r\n\r\nWell, I''m not going anywhere! I have brew to make.\r\n\r\nIf you help us maybe we can all come to a mutually beneficial agreement. I give them some brew, they stop trying to kill us.', 0),
  (31732, 0, 0, 0, 0, 0, 0, 0, 0, 'A proper welcome for the Horde to this new land!', 0),
  (31733, 0, 0, 0, 0, 0, 0, 0, 0, '''Bout time you showed up, lassie! Let''s do some damage!', 0),
  (31734, 0, 0, 0, 0, 0, 0, 0, 0, 'With those wagons our of commission, we can turn our attention to the commander.', 0),
  (31735, 0, 0, 0, 0, 0, 0, 0, 0, 'We''ll catch up with him aggain. I''m sure of it.', 0),
  (31736, 0, 0, 0, 0, 0, 0, 0, 0, 'When the mist fell, we knew it would only be a matter of time before visitors arrived.$B$BWe could not have predicted it would be like this.', 0),
  (31737, 0, 0, 0, 0, 0, 0, 0, 0, 'I am glad you took responsibility for your actions. Left unchecked, negative emotions can quickly overwhelm an individual here, just as they started to overwhelm the one you call "Rell."', 0),
  (31784, 0, 0, 0, 0, 0, 0, 0, 0, 'You did well to bring this egg to me. We will take good care of it, $n.', 0),
  (32035, 0, 0, 0, 0, 0, 0, 0, 0, 'Greetings, $c. Welcome to the Silken Fields.', 0),
  (32678, 0, 0, 0, 0, 0, 0, 0, 0, 'We must move quickly, $n! The others have gone ahead of us, but i will brief you in the flight over.', 0),
  (32679, 0, 0, 0, 0, 0, 0, 0, 0, 'We must move quickly, $n! The others have gone ahead of us, but i will brief you in the flight over.', 0);
